module.exports = /*#__PURE__*/JSON.parse('{"tag":{"label":"CAA","permalink":"/doc-tags/caa","allTagsPath":"/doc-tags","count":17,"items":[{"id":"sk/knifes/K000104-SPARX_AI_KERNARO_IN_SDLC/K000104_SK","title":"AI KERNARO","description":"---","permalink":"/sk/knifes/K000104-SPARX_AI_KERNARO_IN_SDLC/"},{"id":"en/knifes/K000103-CAA_IN_SDLC/K000103","title":"K000103 – Context Aware Approach in SDLC","description":"Context Aware Approach (CAA) applied to Solution Development Life Cycle — why context must be understood before any tool or technology decision is made.","permalink":"/en/knifes/K000103-CAA_IN_SDLC/"},{"id":"sk/knifes/K000103-CAA_IN_SDLC/K000103_SK","title":"K000103 – Context Aware Approach v SDLC","description":"Context Aware Approach (CAA) aplikovaný na Solution Development Life Cycle — prečo kontext musí byť pochopený skôr, než sa urobí akékoľvek technologické rozhodnutie.","permalink":"/sk/knifes/K000103-CAA_IN_SDLC/"},{"id":"sk/knifes/K000106-SSOTandTSSOT/K000106_SK","title":"K000106 – SSOT a TSSOT: Koľko právd treba na úspešné riešenie?","description":"Single Source of Truth a Trusted Single Source of Truth — prečo konzistentné, overené dáta sú predpokladom úspešných riešení, efektívnej AI a zdieľaného porozumenia naprieč fázami SDLC.","permalink":"/sk/knifes/K000106-SSOTandTSSOT/"},{"id":"en/knifes/K000106-SSOTandTSSOT/K000106_EN","title":"K000106 – SSOT and TSSOT: How Many Truths Does It Take to Deliver a Successful Solution?","description":"Single Source of Truth and Trusted Single Source of Truth — why consistent, verified data is the prerequisite for successful solutions, effective AI, and shared understanding across SDLC phases.","permalink":"/en/knifes/K000106-SSOTandTSSOT/"},{"id":"en/knifes/K000107_TaxonomyAndOntology/K000107-APV-index","title":"K000107 – APV: Assets, Perspectives, Views","description":"APV emerged from production lines, not academic research. How a framework built on Technical Cybernetics, Six Sigma, and manufacturing quality principles solves the vocabulary gap in IT and SDLC.","permalink":"/en/knifes/K000107_TaxonomyAndOntology/K000107-APV-index"},{"id":"sk/knifes/K000107_TaxonomyAndOntology/K000107-APV-index","title":"K000107 – APV: Assets, Perspectives, Views","description":"APV nevznikol z akademického výskumu. Vznikol na výrobných linkách. Ako rámec postavený na Technickej kybernetike, Six Sigma a výrobnej kvalite rieši medzeru v slovníku IT a SDLC.","permalink":"/sk/knifes/K000107_TaxonomyAndOntology/K000107-APV-index"},{"id":"en/knifes/K000107_TaxonomyAndOntology/K000107-SFIA-index","title":"K000107 – SFIA: Skills Framework for the Information Age","description":"SFIA is not yet an ISO standard — but it is the closest thing the IT industry has to a shared vocabulary for skills. A practical guide to using SFIA in SDLC teams: what it is, where it came from, and how to apply it without a full programme.","permalink":"/en/knifes/K000107_TaxonomyAndOntology/K000107-SFIA-index"},{"id":"sk/knifes/K000107_TaxonomyAndOntology/K000107-SFIA-index","title":"K000107 – SFIA: Skills Framework for the Information Age","description":"SFIA ešte nie je ISO štandardom — ale je to najbližšie, čo IT priemysel má k spoločnému slovníku pre zručnosti. Praktický návod na používanie SFIA v SDLC tímoch.","permalink":"/sk/knifes/K000107_TaxonomyAndOntology/K000107-SFIA-index"},{"id":"sk/knifes/K000107_TaxonomyAndOntology/K000107_SK","title":"K000107 – Taxonómia a ontológia v SDLC","description":"Prečo každá veda, ktorá sa chce nazývať vedou, buduje pojmový slovník — a prečo informatika stále dobieha. Praktické rámce: APV, SFIA, TBM a ich využitie naprieč SDLC.","permalink":"/sk/knifes/K000107_TaxonomyAndOntology/"},{"id":"en/knifes/K000107_TaxonomyAndOntology/K000107_EN","title":"K000107 – Taxonomy and Ontology in SDLC","description":"When will IT finally use the full power of taxonomy and ontology? ITSM, Cybersecurity, TBM — taxonomy already exists in IT.  So why does every project still start a new vocabulary from scratch?  Practical frameworks: APV, SFIA, TBM, and how to finally put them to work across SDLC.","permalink":"/en/knifes/K000107_TaxonomyAndOntology/"},{"id":"en/knifes/K000107_TaxonomyAndOntology/K000107-TBM-index","title":"K000107 – TBM: Technology Business Management","description":"TBM Taxonomy connects technology spending to business value. How TBM Council formalised the vocabulary of IT costs — and how platforms like Yärken implement it at scale.","permalink":"/en/knifes/K000107_TaxonomyAndOntology/K000107-TBM-index"},{"id":"sk/knifes/K000107_TaxonomyAndOntology/K000107-TBM-index","title":"K000107 – TBM: Technology Business Management","description":"TBM Taxonómia prepája IT výdavky s obchodnou hodnotou. Ako TBM Council formalizoval slovník IT nákladov — a ako platformy ako Yärken ho implementujú vo veľkom.","permalink":"/sk/knifes/K000107_TaxonomyAndOntology/K000107-TBM-index"},{"id":"en/knifes/K000108-QRM/K000108_EN","title":"K000108 – Quick Response Manufacturing (QRM)","description":"QRM is a company-wide strategy for reducing lead times — invented by Rajan Suri in the 1990s. Originally designed for manufacturing, QRM explicitly extends to office and knowledge work processes, making it directly relevant to SDLC and IT delivery.","permalink":"/en/knifes/K000108-QRM/"},{"id":"sk/knifes/K000108-QRM/K000108_SK","title":"K000108 – Quick Response Manufacturing (QRM)","description":"QRM je celopodniková stratégia pre skracovanie lead time — vynájdená Rajanom Surim v 90. rokoch. Pôvodne navrhnutá pre výrobu, QRM explicitne rozširuje svoje princípy na kancelárske a znalostné procesy, čo ju robí priamo relevantnou pre SDLC a IT dodávku.","permalink":"/sk/knifes/K000108-QRM/"},{"id":"sk/knifes/K000109-ESCO-SFIA-CAA/K000109_SK","title":"K000109 – ESCO, SFIA a CAA: Tri vrstvy správy zručností v IT organizáciách","description":"Trojvrstvový model správy zručností v IT: ESCO ako ontologický základ, SFIA ako operačný rámec a CAA ako aplikačná vrstva. Prečo kvalita taxonómie priamo určuje kvalitu výstupov AI.","permalink":"/sk/knifes/K000109-ESCO-SFIA-CAA/"},{"id":"en/knifes/K000109-ESCO-SFIA-CAA/K000109_EN","title":"K000109 – ESCO, SFIA and CAA: Three Layers of Skills Governance in IT Organizations","description":"A three-layer model for skills governance in IT: ESCO as the ontological foundation, SFIA as the operational framework, and CAA as the application layer. Why taxonomy quality directly determines AI output quality.","permalink":"/en/knifes/K000109-ESCO-SFIA-CAA/"}],"unlisted":false}}');

